create or replace function public.my_course_access(p_course_id uuid) returns jsonb language sql stable security definer set search_path to public, pg_temp as $$ select jsonb_build_object('paid',public.subscription_course_is_paid(p_course_id),'has_access',public.subscription_access_ok(public.auth_student_id(),p_course_id),'status',s.status,'access_until',s.access_until,'tariff_id',(select t.id from public.subscription_tariffs t where t.course_id=p_course_id and t.is_active order by (t.id=s.tariff_id) desc nulls last,t.period_months,t.sort_order,t.price_rub,t.id limit 1)) from (select 1) one left join public.student_subscriptions s on s.student_id=public.auth_student_id() and s.course_id=p_course_id; $$;
